/// The calls Go makes of the host, on the main thread.
public protocol HostCalls: AnyObject {
    /// the app's bundle and the system's settings, asked once at start
    func appInfo() -> AppInfoReply
    /// the name of the system's time zone; any thread
    func timeZone() -> TimeZoneReply
    /// the appearance and the accessibility preferences
    func theme() -> ThemeReply
    /// the appearance the app asks for: "light", "dark" or "system"
    func setAppearance(_ c: SetAppearanceCall)
    /// the Wi-Fi multicast lock the local network's discovery holds, or gives back
    func multicastLock(_ c: MulticastLockCall)
    /// the screen's size in DIPs and scale
    func screen() -> ScreenReply
    /// a line the app wrote to its standard output or error
    func log(_ c: LogCall)
    /// the screen's content: a web view, or a surface for native UI
    func createWindow(_ c: CreateWindowCall) -> CreateWindowReply
    /// the window's content presented its first frame
    func firstFrame(_ c: FirstFrameCall)
    /// where a surface shows the windows it holds (Parent), under it, in the order painted; the others hide. Places: encoded by Go (encodePlaces)
    func placeViews(_ c: PlaceViewsCall)
    func showWindow(_ c: ShowWindowCall)
    func hideWindow(_ c: HideWindowCall)
    func closeWindow(_ c: CloseWindowCall)
    func setBackground(_ c: SetBackgroundCall)
    func focus(_ c: FocusCall)
    /// the window's title, which a navigation bar shows
    func setTitle(_ c: SetTitleCall)
    /// a bar of tabs, whose tabs AddTab adds before ShowTabs shows it
    func createTabs(_ c: CreateTabsCall)
    func addTab(_ c: AddTabCall)
    func showTabs(_ c: ShowTabsCall)
    func selectTab(_ c: SelectTabCall)
    func setTabBadge(_ c: SetTabBadgeCall)
    func closeTabs(_ c: CloseTabsCall)
    /// shows Child over Parent in Parent's stack, under a bar with its Title and a back button
    func pushWindow(_ c: PushWindowCall)
    func popWindow(_ c: PopWindowCall)
    func loadURL(_ c: LoadURLCall)
    func loadHTML(_ c: LoadHTMLCall)
    func reload(_ c: ReloadCall)
    func stopLoading(_ c: StopLoadingCall)
    func goBack(_ c: GoBackCall)
    func goForward(_ c: GoForwardCall)
    func eval(_ c: EvalCall)
    /// runs Body as an async function's; AsyncResult answers
    func callAsync(_ c: CallAsyncCall)
    func setZoom(_ c: SetZoomCall)
    func setUserAgent(_ c: SetUserAgentCall)
    func setUserScripts(_ c: SetUserScriptsCall)
    /// a PNG of the page; Captured answers
    func capturePage(_ c: CapturePageCall)
    func userAgent(_ c: UserAgentCall) -> UserAgentReply
    /// the status and headers of a SchemeRequest (Header: names and values in turn)
    func schemeRespond(_ c: SchemeRespondCall)
    func schemeData(_ c: SchemeDataCall)
    func schemeFinish(_ c: SchemeFinishCall)
    func schemeFail(_ c: SchemeFailCall)
    /// an alert; MessageBoxResult answers
    func messageBox(_ c: MessageBoxCall)
    /// the system's picker of documents; FilesResult answers with copies the app may read
    func openFiles(_ c: OpenFilesCall)
    /// the share sheet of a file, as the place to save it
    func shareFile(_ c: ShareFileCall)
    func clipboardText() -> ClipboardTextReply
    func setClipboardText(_ c: SetClipboardTextCall)
    /// opens a URL in the app the system has for it
    func openURL(_ c: OpenURLCall) -> OpenURLReply
    func secretGet(_ c: SecretGetCall) -> SecretGetReply
    func secretSet(_ c: SecretSetCall) -> SecretSetReply
    func secretDelete(_ c: SecretDeleteCall) -> SecretDeleteReply
    /// a local notification; NotifyDone answers once the system has it
    func notify(_ c: NotifyCall)
    func removeNotification(_ c: RemoveNotificationCall)
    func removeAllNotifications()
    /// keeps the screen on while the app shows
    func keepAwake(_ c: KeepAwakeCall)
    func networkStatus() -> NetworkStatusReply
    /// starts NetworkChanged
    func watchNetwork()
    func battery() -> BatteryReply
    /// the icons of the system's bars ("auto", "light" or "dark"), and whether the bars hide
    func setSystemBars(_ c: SetSystemBarsCall)
    /// the orientations the screen may take: 1 portrait, 2 upside down, 4 landscape left, 8 landscape right; 0 any
    func setOrientations(_ c: SetOrientationsCall)
    /// the share sheet of text, a link and files; ShareResult answers
    func share(_ c: ShareCall)
    /// the system's picker of where to keep a copy of Path under Name; FilesResult answers with the place, empty when dismissed
    func saveFile(_ c: SaveFileCall)
    func clipboardImage() -> ClipboardImageReply
    func setClipboardImage(_ c: SetClipboardImageCall)
    /// the system's menu at a point of the window: Items are encoded by Go (encodeMenu); MenuPicked answers with the item's ID, 0 when dismissed
    func popupMenu(_ c: PopupMenuCall)
    /// the buttons at the end of the window's navigation bar; BarItemClicked tells which: titles, symbols and icons by index
    func setBarItems(_ c: SetBarItemsCall)
    /// a call of a plugin's native code: Args and PluginResult's Result are JSON
    func pluginCall(_ c: PluginCallCall)
    /// opens the sound's output: stereo at Rate frames a second, holding about Ahead milliseconds; on the caller's thread
    func audioOpen(_ c: AudioOpenCall) -> AudioOpenReply
    /// plays interleaved stereo float32 samples after those written, waiting while the output holds enough; on the caller's thread
    func audioWrite(_ c: AudioWriteCall) -> AudioWriteReply
    func audioClose() -> AudioCloseReply
    /// "selection", "light", "medium", "heavy", "success", "warning" or "error"
    func haptic(_ c: HapticCall)
    /// asks for a Frame at the next refresh of the display
    func requestFrame(_ c: RequestFrameCall)
    /// whether the keyboard shows and what for: the input's traits (platform.TextTraits), and its text. Show counts the requests to show the keyboard again. Offsets are UTF-16 units of the document, of which Text is the part around the selection, from Base; MarkStart is -1 without marked text. A window without Document takes text without one, as a terminal: the keyboard sees none
    func setTextInput(_ c: SetTextInputCall)
    /// the pointer's shape, for a mouse or a trackpad
    func setCursor(_ c: SetCursorCall)
    /// the tree of accessible elements changed; Focus names the one with the focus
    func accessibilityChanged(_ c: AccessibilityChangedCall)
    func announce(_ c: AnnounceCall)
    /// the system's edit menu at a point, with the actions given (cut, copy, paste, selectAll); TextCommand answers
    func showMenu(_ c: ShowMenuCall)
    /// whether the content takes the system's back
    func setBackAvailable(_ c: SetBackAvailableCall)
    /// the system's magnifier of what is at a point
    func showMagnifier(_ c: ShowMagnifierCall)
    func hideMagnifier(_ c: HideMagnifierCall)
    /// the metrics of a font (Android's Paint): ascent and descent, x-height, underline and strikethrough
    func textMetrics(_ c: TextMetricsCall) -> TextMetricsReply
    /// how wide each of Texts is in a font, kerned unless NoKern
    func measureText(_ c: MeasureTextCall) -> MeasureTextReply
    /// the advance of each UTF-16 unit of Text laid out as a whole (getTextRunAdvances)
    func textAdvances(_ c: TextAdvancesCall) -> TextAdvancesReply
    /// draws Text in white at Scale pixels per DIP, its pen DX pixels right of a pixel's edge: its ink's box from the pen and its pixels, a byte of coverage each, or premultiplied RGBA when Color
    func drawText(_ c: DrawTextCall) -> DrawTextReply
    /// adds a font file under Family, or its own family when empty
    func registerFont(_ c: RegisterFontCall) -> RegisterFontReply
}

/// Runs a call on h and encodes its reply, nil for a call not waited for.
public func dispatchCall(_ h: HostCalls, _ buf: UnsafeRawBufferPointer) -> [UInt8]? {
    var r = WireReader(buf)
    var w = WireWriter()
    switch r.uvarint() {
    case 1:
        h.appInfo().encode(&w)
        return w.buf
    case 2:
        h.timeZone().encode(&w)
        return w.buf
    case 3:
        h.theme().encode(&w)
        return w.buf
    case 4:
        h.setAppearance(SetAppearanceCall(&r))
        return nil
    case 5:
        h.multicastLock(MulticastLockCall(&r))
        return nil
    case 6:
        h.screen().encode(&w)
        return w.buf
    case 7:
        h.log(LogCall(&r))
        return nil
    case 8:
        h.createWindow(CreateWindowCall(&r)).encode(&w)
        return w.buf
    case 9:
        h.firstFrame(FirstFrameCall(&r))
        return nil
    case 10:
        h.placeViews(PlaceViewsCall(&r))
        return nil
    case 11:
        h.showWindow(ShowWindowCall(&r))
        return nil
    case 12:
        h.hideWindow(HideWindowCall(&r))
        return nil
    case 13:
        h.closeWindow(CloseWindowCall(&r))
        return nil
    case 14:
        h.setBackground(SetBackgroundCall(&r))
        return nil
    case 15:
        h.focus(FocusCall(&r))
        return nil
    case 16:
        h.setTitle(SetTitleCall(&r))
        return nil
    case 17:
        h.createTabs(CreateTabsCall(&r))
        return nil
    case 18:
        h.addTab(AddTabCall(&r))
        return nil
    case 19:
        h.showTabs(ShowTabsCall(&r))
        return nil
    case 20:
        h.selectTab(SelectTabCall(&r))
        return nil
    case 21:
        h.setTabBadge(SetTabBadgeCall(&r))
        return nil
    case 22:
        h.closeTabs(CloseTabsCall(&r))
        return nil
    case 23:
        h.pushWindow(PushWindowCall(&r))
        return nil
    case 24:
        h.popWindow(PopWindowCall(&r))
        return nil
    case 25:
        h.loadURL(LoadURLCall(&r))
        return nil
    case 26:
        h.loadHTML(LoadHTMLCall(&r))
        return nil
    case 27:
        h.reload(ReloadCall(&r))
        return nil
    case 28:
        h.stopLoading(StopLoadingCall(&r))
        return nil
    case 29:
        h.goBack(GoBackCall(&r))
        return nil
    case 30:
        h.goForward(GoForwardCall(&r))
        return nil
    case 31:
        h.eval(EvalCall(&r))
        return nil
    case 32:
        h.callAsync(CallAsyncCall(&r))
        return nil
    case 33:
        h.setZoom(SetZoomCall(&r))
        return nil
    case 34:
        h.setUserAgent(SetUserAgentCall(&r))
        return nil
    case 35:
        h.setUserScripts(SetUserScriptsCall(&r))
        return nil
    case 36:
        h.capturePage(CapturePageCall(&r))
        return nil
    case 37:
        h.userAgent(UserAgentCall(&r)).encode(&w)
        return w.buf
    case 38:
        h.schemeRespond(SchemeRespondCall(&r))
        return nil
    case 39:
        h.schemeData(SchemeDataCall(&r))
        return nil
    case 40:
        h.schemeFinish(SchemeFinishCall(&r))
        return nil
    case 41:
        h.schemeFail(SchemeFailCall(&r))
        return nil
    case 42:
        h.messageBox(MessageBoxCall(&r))
        return nil
    case 43:
        h.openFiles(OpenFilesCall(&r))
        return nil
    case 44:
        h.shareFile(ShareFileCall(&r))
        return nil
    case 45:
        h.clipboardText().encode(&w)
        return w.buf
    case 46:
        h.setClipboardText(SetClipboardTextCall(&r))
        return nil
    case 47:
        h.openURL(OpenURLCall(&r)).encode(&w)
        return w.buf
    case 48:
        h.secretGet(SecretGetCall(&r)).encode(&w)
        return w.buf
    case 49:
        h.secretSet(SecretSetCall(&r)).encode(&w)
        return w.buf
    case 50:
        h.secretDelete(SecretDeleteCall(&r)).encode(&w)
        return w.buf
    case 51:
        h.notify(NotifyCall(&r))
        return nil
    case 52:
        h.removeNotification(RemoveNotificationCall(&r))
        return nil
    case 53:
        h.removeAllNotifications()
        return nil
    case 54:
        h.keepAwake(KeepAwakeCall(&r))
        return nil
    case 55:
        h.networkStatus().encode(&w)
        return w.buf
    case 56:
        h.watchNetwork()
        return nil
    case 57:
        h.battery().encode(&w)
        return w.buf
    case 58:
        h.setSystemBars(SetSystemBarsCall(&r))
        return nil
    case 59:
        h.setOrientations(SetOrientationsCall(&r))
        return nil
    case 60:
        h.share(ShareCall(&r))
        return nil
    case 61:
        h.saveFile(SaveFileCall(&r))
        return nil
    case 62:
        h.clipboardImage().encode(&w)
        return w.buf
    case 63:
        h.setClipboardImage(SetClipboardImageCall(&r))
        return nil
    case 64:
        h.popupMenu(PopupMenuCall(&r))
        return nil
    case 65:
        h.setBarItems(SetBarItemsCall(&r))
        return nil
    case 66:
        h.pluginCall(PluginCallCall(&r))
        return nil
    case 67:
        h.audioOpen(AudioOpenCall(&r)).encode(&w)
        return w.buf
    case 68:
        h.audioWrite(AudioWriteCall(&r)).encode(&w)
        return w.buf
    case 69:
        h.audioClose().encode(&w)
        return w.buf
    case 70:
        h.haptic(HapticCall(&r))
        return nil
    case 71:
        h.requestFrame(RequestFrameCall(&r))
        return nil
    case 72:
        h.setTextInput(SetTextInputCall(&r))
        return nil
    case 73:
        h.setCursor(SetCursorCall(&r))
        return nil
    case 74:
        h.accessibilityChanged(AccessibilityChangedCall(&r))
        return nil
    case 75:
        h.announce(AnnounceCall(&r))
        return nil
    case 76:
        h.showMenu(ShowMenuCall(&r))
        return nil
    case 77:
        h.setBackAvailable(SetBackAvailableCall(&r))
        return nil
    case 78:
        h.showMagnifier(ShowMagnifierCall(&r))
        return nil
    case 79:
        h.hideMagnifier(HideMagnifierCall(&r))
        return nil
    case 80:
        h.textMetrics(TextMetricsCall(&r)).encode(&w)
        return w.buf
    case 81:
        h.measureText(MeasureTextCall(&r)).encode(&w)
        return w.buf
    case 82:
        h.textAdvances(TextAdvancesCall(&r)).encode(&w)
        return w.buf
    case 83:
        h.drawText(DrawTextCall(&r)).encode(&w)
        return w.buf
    case 84:
        h.registerFont(RegisterFontCall(&r)).encode(&w)
        return w.buf
    default:
        return nil
    }
}

/// Encodes the events the host sends Go.
public enum Event {
    /// the app finished launching
    public static func ready() -> [UInt8] {
        var w = WireWriter()
        w.uvarint(1)
        return w.buf
    }
    /// the app is in front, or no longer
    public static func active(active: Bool) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(2)
        w.bool(active)
        return w.buf
    }
    /// the app goes to the background (true) or came back. The host waits: iOS ends apps that use the GPU in the background, so that frames stop before it returns
    public static func background(background: Bool) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(3)
        w.bool(background)
        return w.buf
    }
    public static func themeChanged() -> [UInt8] {
        var w = WireWriter()
        w.uvarint(4)
        return w.buf
    }
    public static func localeChanged() -> [UInt8] {
        var w = WireWriter()
        w.uvarint(5)
        return w.buf
    }
    public static func timeZoneChanged(id: String) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(6)
        w.string(id)
        return w.buf
    }
    public static func openURLs(urls: [String]) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(7)
        w.strings(urls)
        return w.buf
    }
    public static func memoryWarning() -> [UInt8] {
        var w = WireWriter()
        w.uvarint(8)
        return w.buf
    }
    /// the process ends once Go answers
    public static func terminating() -> [UInt8] {
        var w = WireWriter()
        w.uvarint(9)
        return w.buf
    }
    /// the window's size in DIPs, the scale, and the insets of what covers it: the system's bars, the cutout, the keyboard
    public static func resized(id: Int, width: Double, height: Double, scale: Double, safeTop: Double, safeLeft: Double, safeBottom: Double, safeRight: Double, keyboard: Double) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(10)
        w.int(id)
        w.float(width)
        w.float(height)
        w.float(scale)
        w.float(safeTop)
        w.float(safeLeft)
        w.float(safeBottom)
        w.float(safeRight)
        w.float(keyboard)
        return w.buf
    }
    /// the system's gesture of going back, as it goes: Phase is "started", "progress" or "cancelled"
    public static func backGesture(id: Int, phase: String, progress: Double) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(11)
        w.int(id)
        w.string(phase)
        w.float(progress)
        return w.buf
    }
    /// a tap on iOS's status bar
    public static func statusBarTapped() -> [UInt8] {
        var w = WireWriter()
        w.uvarint(12)
        return w.buf
    }
    /// a finger went down on a view a surface holds, which takes it
    public static func viewPressed(id: Int, x: Double, y: Double) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(13)
        w.int(id)
        w.float(x)
        w.float(y)
        return w.buf
    }
    public static func pluginResult(req: Int, result: String, error: String, code: String) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(14)
        w.int(req)
        w.string(result)
        w.string(error)
        w.string(code)
        return w.buf
    }
    /// an event of a plugin's native code: Data is JSON
    public static func pluginEvent(plugin: String, name: String, data: String) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(15)
        w.string(plugin)
        w.string(name)
        w.string(data)
        return w.buf
    }
    public static func networkChanged(online: Bool, metered: Bool) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(16)
        w.bool(online)
        w.bool(metered)
        return w.buf
    }
    public static func shareResult(req: Int, error: String) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(17)
        w.int(req)
        w.string(error)
        return w.buf
    }
    public static func menuPicked(req: Int, item: Int) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(18)
        w.int(req)
        w.int(item)
        return w.buf
    }
    public static func barItemClicked(id: Int, index: Int) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(19)
        w.int(id)
        w.int(index)
        return w.buf
    }
    /// the user chose tab Index
    public static func tabSelected(id: Int, index: Int) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(20)
        w.int(id)
        w.int(index)
        return w.buf
    }
    /// the window left its stack: the back button, a swipe, Android's back, or PopWindow
    public static func popped(id: Int) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(21)
        w.int(id)
        return w.buf
    }
    /// Android's back: whether the app took it
    public static func backPressed(id: Int) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(22)
        w.int(id)
        return w.buf
    }
    /// a message the page's bridge posted
    public static func message(id: Int, text: String) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(23)
        w.int(id)
        w.string(text)
        return w.buf
    }
    public static func willNavigate(id: Int, url: String, mainFrame: Bool, userInitiated: Bool, unasked: Bool, reload: Bool) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(24)
        w.int(id)
        w.string(url)
        w.bool(mainFrame)
        w.bool(userInitiated)
        w.bool(unasked)
        w.bool(reload)
        return w.buf
    }
    /// window.open or a link to _blank: whether the app opened it
    public static func newWindow(id: Int, url: String, userInitiated: Bool) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(25)
